	//   A: scalar ^ k_vec ^ i_vec  => dims (i, k), k is the innermost (row-major).
	//   B: scalar ^ k_vec ^ j_vec  => dims (k, j), k is the innermost
	//      (column-major in the logical (k, j) space). This makes B[k, j]
	//      contiguous in k, which matches the innermost reduction loop and
	//      gives unit-stride accesses in both A and B along k.
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // C: i x j, row-major over j
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k, row-major over k
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec); // B: k x j, column-major in k
} tuning;

// Array initialization
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto ni = C | get_length<'i'>();
		C[state] = (num_t)((i * j + 1) % ni) / ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto nk = A | get_length<'k'>();
		A[state] = (num_t)(i * (k + 1) % nk) / nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	// (Layout change of B does not affect this formula; indices are by name.)
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		auto nj = B | get_length<'j'>();
		B[state] = (num_t)(k * (j + 2) % nj) / nj;
	});
}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimized implementation:
//  - Fuses the "C *= beta" and the A*B accumulation into a single pass
//    per C(i,j):   C[i,j] = beta * C[i,j] + alpha * sum_k A[i,k]*B[k,j].
//  - Blocks all three dimensions (i, j, k) using into_blocks_dynamic to
//    improve cache locality. Dynamic variant handles edge tiles safely.
//  - Uses B with k as the innermost/contiguous dimension so that the
//    reduction over k has unit-stride memory accesses in both A and B.
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Tile sizes chosen to balance cache locality and overhead.
	// They can be tuned further for a given target.
	constexpr auto tile_i = noarr::lit<64>;
	constexpr auto tile_j = noarr::lit<64>;
	constexpr auto tile_k = noarr::lit<32>;

	// Block all three logical dimensions.
	// into_blocks_dynamic<Dim, DimMajor, DimMinor, DimIsPresent>(block_size)
	// splits Dim into:
	//   - DimMajor: block index (I/J/K below),
	//   - DimMinor: index within a block (i/j/k),
	//   - DimIsPresent: guard dimension (r/s/t) that is empty for out-of-range
	//     elements in the last, partial block.
	//
	// We compose three such proto-structures to block i, j, and k.
	auto blocking =
		into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i) ^ // 'r' guards partial rows
		into_blocks_dynamic<'j', 'J', 'j', 's'>(tile_j) ^ // 's' guards partial cols
		into_blocks_dynamic<'k', 'K', 'k', 't'>(tile_k);  // 't' guards partial k

#pragma scop
	traverser(C, A, B)
		// Apply the blocking transformation only to the traversal order.
		.order(blocking)
		// Outer tiling loops over tiles of C: (I, J) index a TI x TJ block.
		.template for_dims<'I', 'J'>([&](auto trav_IJ) {
			// For the current (I,J) tile, iterate all valid (i,j) pairs in it.
			// Dimensions 'r' and 's' are presence flags that ensure we skip
			// elements beyond ni/nj in the last partial tiles.
			trav_IJ.template for_dims<'i', 'r', 'j', 's'>([&](auto trav_ij) {
				// trav_ij now identifies a single logical (i,j) element
				// (plus tile indices, which C ignores).
				auto state_ij = trav_ij.state();

				// Fused scaling and accumulation:
				//   acc = beta * C_old[i,j] + alpha * sum_k A[i,k]*B[k,j].
				// We load and store C[i,j] exactly once.
				num_t acc = beta * C[state_ij];

				// Reduce over the entire k-dimension for this fixed (i,j):
				// trav_ij has the remaining k-related dimensions ('K', 'k', 't'),
				// and for_each walks all valid combinations of those.
				trav_ij.for_each([&](auto state) {
					// state carries the same i,j as state_ij plus the current k.
					acc += alpha * A[state] * B[state];
				});

				// Write the final accumulated value back to C.
				C[state_ij] = acc;
			});
		});
#pragma endscop
}

} // namespace

