		^ into_blocks_dynamic<'j', 'J', 'j', 's'>(noarr::lit<J_BLOCK>);
	auto B_blk = B
		^ into_blocks_dynamic<'j', 'J', 'j', 's'>(noarr::lit<J_BLOCK>);

