	//   for i:
	//     for each column block J:
	//       // Scale C[i, J-block] by beta
	//       for j in block(J):
	//         C[i, j] *= beta;
	//
	//     for each column block J:
	//       for k:
	//         let a_ik = A[i, k];
	//         for j in block(J):
	//           C[i, j] += alpha * a_ik * B[k, j];
	//
