	// but improves data locality and reduces redundant work.
	traverser(C_blk, A, B_blk).template for_dims<'i'>([=](auto trav_i) {
		// Outer loop over rows i of C and A.

		// -----------------------------------------------------------------
		// 1) Scale C by beta: C[i, j] *= beta
		//    Done tile-by-tile along the j dimension for better locality.
		// -----------------------------------------------------------------
