		// 2) GEMM update: C[i, j] += alpha * sum_k A[i, k] * B[k, j]
		//    We still accumulate over the full k-range, but operate on
		//    column tiles (J) and reuse A[i, k] across all j in a tile.
		// -----------------------------------------------------------------
		trav_i.template for_dims<'J'>([=](auto trav_iJ) {
			// Fixed row i and column block J.
			trav_iJ.template for_dims<'k'>([=](auto trav_iJk) {
