		// 1) Scale the entire i-th row of C by beta:
		//    for j: C[i,j] *= beta;
		// ------------------------------------------------------------------
		//
		// `trav_i` has dimension 'i' fixed; remaining relevant dim for C is 'j'.
		// We iterate only over 'j' using for_each<'j'> so that we do not touch
		// the reduction dimension 'k' here.
		trav_i.template for_each<'j'>([=](auto state_ij) {
			// state_ij carries indices (i, j); 'k' is intentionally unset.
			C[state_ij] *= beta;
		});

