		//   - loads A[i,k] once per (i,k),
		//   - keeps the inner loop over 'j', which is contiguous in memory
		//     for both C and B with the current layouts.
		// ------------------------------------------------------------------
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			// trav_ik has indices (i, k) fixed.
			// Precompute scaled A[i,k] once and reuse in the j-loop.
			num_t a_ik = alpha * A[trav_ik];

			// Inner loop over all columns j. This matches the row-major
			// layout where j is the fastest-varying dimension in C and B.
			trav_ik.template for_each<'j'>([&](auto state_ijk) {
				// state_ijk carries indices (i, k, j); C ignores 'k',
				// B ignores 'i', but both see the correct (i,j) / (k,j).
				C[state_ijk] += a_ik * B[state_ijk];
			});
		});
	});
#pragma endscop
