}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// The original kernel (for each i):
//   1) for all j: C[i,j] *= beta;
//   2) for all k,j: C[i,j] += alpha * A[i,k] * B[k,j];
//
// The optimized version below computes the same result but:
//
//   - fuses the beta scaling with the multiplication for better locality,
//   - tiles the 'i' and 'j' dimensions using into_blocks_dynamic to keep
//     a working C tile in cache,
//   - iterates with j innermost in the multiplication phase so that
//     accesses to C[i,j] and B[k,j] are unit-stride (row-major),
//   - uses Noarr traversers exclusively to express all loop nests.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	// Cache/blocking parameters.
	// These are conservative, fixed compile-time values; for a real
	// application they would be tuned for the target machine.
	constexpr std::size_t tile_i = 64; // tile height  along rows (i)
	constexpr std::size_t tile_j = 64; // tile width   along cols (j)

#pragma scop
	// We create a traverser over all three matrices and apply a 2D
	// blocking (tiling) transformation to the i and j dimensions.
	//
	// into_blocks_dynamic<'i','I','i','r'>(tile_i) splits 'i' into:
	//   - 'I'  : block index,
	//   - 'i'  : index within the block,
	//   - 'r'  : presence dimension (length 0 or 1) for partial tiles.
	//
	// The same holds for j with ('J','j','s').
	//
	// Dynamic blocking is used so that we correctly handle problem
	// sizes not divisible by tile_i/tile_j.
	traverser(C, A, B)
		.order(
			into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i) ^
			into_blocks_dynamic<'j', 'J', 'j', 's'>(tile_j)
		)

		// Outer loop over i-tiles ('I')
		.template for_dims<'I'>([=](auto trav_I) {

			// Loop over rows inside the current i-tile.
			// The pair ('i','r') iterates only valid global i-indices
			// thanks to the presence dimension 'r'.
			trav_I.template for_dims<'i', 'r'>([=](auto trav_Ii) {

				// -----------------------------------------------------------------
				// 1) Scale C[i, j] by beta for this row i, tile by tile in 'J'.
				//    This reproduces the first part of the original kernel:
				//        for (j) C[i][j] *= beta;
				// -----------------------------------------------------------------
				trav_Ii.template for_dims<'J'>([=](auto trav_IiJ) {
					// Iterate all valid j indices inside this J-tile.
					// 's' is the presence dimension for partial tiles.
					trav_IiJ.template for_each<'j', 's'>([=](auto state_ij) {
						// state_ij contains (at least) the current i and j.
						// C's layout only depends on 'i' and 'j', so extra
						// indices like 'I', 'J', 'r', 's' are ignored.
						C[state_ij] *= beta;
					});
				});

				// -----------------------------------------------------------------
				// 2) GEMM accumulation:
				//
				//    For this fixed row i, we now execute:
				//        for (k)
				//          for (j) C[i,j] += alpha * A[i,k] * B[k,j];
				//
				//    Loop order is:
				//        i (fixed here) -> k -> J -> j
				//
				//    This means:
				//      - For each k we compute a_val = alpha * A[i,k]
				//        once and reuse it across all j in the J-tiles.
				//      - The innermost dimension is j, which is contiguous
				//        in both C and B (row-major layouts), giving
				//        unit-stride memory access and good vectorization.
				// -----------------------------------------------------------------
				trav_Ii.template for_dims<'k'>([=](auto trav_Iik) {
					// trav_Iik has i and k fixed; j- and J-dimensions are
					// still free. Its state() holds the current (i,k) pair.

					auto state_ik = trav_Iik.state();
					// Pre-scale A[i,k] by alpha; this value is reused across
					// all j in the current row and all J-tiles.
					num_t a_val = alpha * A[state_ik];

					// For the current (i,k), update every column j, grouped
					// into tiles 'J'.
					trav_Iik.template for_dims<'J'>([=](auto trav_IikJ) {
						// Iterate all valid j in this J-tile.
						trav_IikJ.template for_each<'j', 's'>([=](auto state) {
							// state now has fixed (i,k) and some (j) within
							// the current J-tile (again guarded by 's').
							//
							// This performs:
							//   C[i,j] += alpha * A[i,k] * B[k,j];
							//
							// Since C[i,j] was already scaled by beta above,
							// this combined with the scaling step is
							// algebraically equivalent to:
							//   C[i,j] = beta * C_old[i,j]
							//            + alpha * sum_k A[i,k] * B[k,j].
							C[state] += a_val * B[state];
						});
					});
				});
			});
		});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;

	// scalars
	num_t alpha;
	num_t beta;

	// lengths proto-structure (applied to all matrices)
	auto set_lengths =
		noarr::set_length<'i'>(ni)
		^ noarr::set_length<'j'>(nj)
		^ noarr::set_length<'k'>(nk);

	// bags for C, A, B with appropriate layouts
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths); // i x j
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // i x k
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // k x j

	// initialize arrays
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gemm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// output to prevent dead-code elimination (similar role as print_array/polybench_prevent_dce)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
