		// Loops:
		//   for i:
		//     for j: C[i,j] *= beta;
		//     for k, j: C[i,j] += alpha * A[i,k] * B[k,j];
		traverser(C, A, B).template for_dims<'i'>([=](auto inner) {
			// First: scale C by beta along j for the current row i.
			inner.template for_each<'j'>([=](auto state) {
				C[state] *= beta;
